import {
  IEquipCategoryDto,
  ISetEquipDto,
  IEquipSetDto,
  IHikingEquipDto,
  IEquipDTO,
  IHikingEquipAddOrUpdateDTO,
  IBackpackDTO,
  ISharedEquipSetDTO,
  IEquipSetListItemDTO,
  IEquipSetAddDTO,
  IEquipSetUpdateDTO,
  IEquipStatDTO,
  IEquipStatUsagesDTO,
} from '../@types/DTO/equip.dto.types';
import {
  IBackpack,
  IEquip,
  IEquipCategory,
  IEquipSet,
  IEquipSetListItem,
  IEquipStatUsage,
  IEquipWithUsagesStat,
  IHikingEquip,
  ISetEquip,
  ISharedEquipSet,
} from '../@types/equip.types';

export const mapEquipSetToFront = (backData: IEquipSetDto): IEquipSet => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.description,
    date_update: new Date(backData.date_update),
    hiking: !backData.id_hiking
      ? null
      : {
          id: +backData.hiking_id,
          name: backData.hiking_name,
          ava: backData.hiking_ava,
          start: new Date(backData.hiking_start),
          finish: new Date(backData.hiking_finish),
        },
    backpack: !backData.id_backpack
      ? null
      : {
          id: +backData.backpack_id,
          name: backData.backpack_name,
          photo: backData.backpack_photo,
          value: +backData.backpack_value,
          weight: +backData.backpack_weight,
        },
    user: {
      id: +backData.id_user,
      name: backData.user_name,
      surname: backData.user_name,
      photo: backData.user_photo,
    },
    share: (backData.share ?? []).map((x) => +x.id),
  };
};

export const mapEquipCategoryToFront = (backData: IEquipCategoryDto): IEquipCategory => {
  return {
    id: +backData.id,
    name: backData.name,
  };
};

export const mapHikingEquipToFront = (backData: IHikingEquipDto): IHikingEquip => {
  return {
    id: +backData.id,
    name: backData.name,
    my: backData.my,
    id_equip: backData.id_equip ? +backData.id_equip : null,
    id_parent: backData.id_parent ? +backData.id_parent : null,
    isConfirm: backData.is_confirm === '1',
    photo: backData.photo,
    fromUser: backData.from_user_id
      ? {
          id: +backData.from_user_id,
          name: backData.from_user_name ?? '',
          photo: backData.from_user_photo ?? '',
        }
      : null,
    user: backData.id_user
      ? {
          id: +backData.id_user,
          name: [backData.uname, backData.usurname].join(' '),
          photo: backData.photo_50,
        }
      : null,
    value: +backData.value,
    weight: +backData.weight,
  };
};

export const mapSetEquipToFront = (backData: ISetEquipDto): ISetEquip => {
  return {
    id: +backData.id,
    name: backData.name,
    idInSet: +backData.iid,
    id_category: backData.id_category ? +backData.id_category : null,
    id_parent: backData.id_parent ? +backData.id_parent : null,
    is_archive: backData.is_archive == '1',
    isCheck: backData.is_check == '1',
    isOnMe: backData.is_on_me == '1',
    is_group: backData.is_group == '1',
    is_musthave: backData.is_musthave == '1',
    owner: !backData.ownerId
      ? null
      : { id: +backData.ownerId, name: backData.ownerName ?? '', photo: backData.ownerPhoto ?? '' },
    photo: backData.photo,
    value: +backData.value,
    weight: +backData.weight,
    amount: +backData.amount,
  };
};

export const mapEquipToFront = (backData: IEquipDTO): IEquip => {
  return {
    id: +backData.id,
    name: backData.name,
    id_category: backData.id_category ? +backData.id_category : null,
    id_parent: backData.id_parent ? +backData.id_parent : null,
    is_archive: backData.is_archive == '1',
    is_group: backData.is_group == '1',
    is_musthave: backData.is_musthave == '1',
    photo: backData.photo,
    value: +backData.value,
    weight: +backData.weight,
  };
};

export const mapEquipToAddUpdateDTO = (equip: IEquip): IHikingEquipAddOrUpdateDTO => {
  return {
    id: equip.id.toString(),
    name: equip.name,
    weight: equip.weight.toString(),
    value: equip.value.toString(),
    photo: equip.photo,
    id_parent: equip.id_parent ? equip.id_parent.toString() : null,
    id_category: equip.id_category ? equip.id_category.toString() : null,
    is_archive: equip.is_archive ? '1' : '0',
    is_musthave: equip.is_musthave ? '1' : '0',
    is_group: equip.is_group ? '1' : '0',
  };
};

export const getEmptyEquip = (): IEquip => {
  return {
    id: 0,
    name: '',
    id_category: null,
    id_parent: null,
    is_archive: false,
    is_group: false,
    is_musthave: false,
    photo: '',
    value: 0,
    weight: 0,
  };
};

export const getEmptyHikingEquip = (patch: Partial<IHikingEquip> = {}): IHikingEquip => {
  return {
    id: 0,
    name: '',
    my: true,
    id_equip: null,
    id_parent: null,
    isConfirm: false,
    photo: '',
    fromUser: null,
    user: null,
    value: 0,
    weight: 0,
    ...patch,
  };
};

export const mapBackpackToFront = (backData: IBackpackDTO): IBackpack => {
  return {
    id: +backData.id,
    name: backData.name,
    weight: +backData.weight,
    value: +backData.value,
    photo: backData.photo,
  };
};

export const mapBackpackToBack = (frontData: IBackpack): IBackpackDTO => {
  return {
    id: frontData.id.toString(),
    name: frontData.name.toString(),
    weight: frontData.weight.toString(),
    value: frontData.value.toString(),
    photo: frontData.photo,
  };
};

export const mapSharedEquipSetToFront = (backData: ISharedEquipSetDTO): ISharedEquipSet => {
  return {
    id: +backData.id,
    id_set: +backData.id_set,
    userFrom: {
      id: +backData.own_id,
      name: backData.own_name,
      surname: backData.own_surname,
      photo: backData.own_photo,
    },
    userTo: !backData.to_user
      ? null
      : {
          id: +backData.to_user,
          name: backData.name,
          surname: backData.surname,
          photo: backData.photo,
        },
  };
};

