export const mapEquipSetListItemToAddDto = (frontData: IEquipSetListItem): IEquipSetAddDTO => {
  return {
    name: frontData.name,
    desc: frontData.description,
    id_backpack: frontData.backpack ? frontData.backpack.id : null,
    id_hiking: frontData.hiking ? frontData.hiking.id : null,
  };
};

export const mapEquipSetListItemToUpdateDto = (
  frontData: IEquipSetListItem,
): IEquipSetUpdateDTO => {
  return {
    ...mapEquipSetListItemToAddDto(frontData),
    id: frontData.id,
  };
};

export const mapEquipStatUsageToFront = (backData: IEquipStatUsagesDTO): IEquipStatUsage => {
  return {
    id: +backData.id,
    name: backData.name,
    description: backData.description,
    date_update: new Date(backData.date_update),
    hiking: !backData.hiking_id
      ? null
      : {
          id: +backData.hiking_id,
          name: backData.hiking_name,
          ava: backData.hiking_ava,
          start: new Date(backData.hiking_start),
          finish: new Date(backData.hiking_finish),
        },
    backpack: !backData.backpack_id
      ? null
      : {
          id: +backData.backpack_id,
          name: backData.backpack_name,
          photo: backData.backpack_photo,
          value: +backData.backpack_value,
          weight: +backData.backpack_weight,
        },
    user: {
      id: 0,
      name: '',
      surname: '',
      photo: '',
    },
    share: [],
    isCheck: backData.is_check == '1',
    isOnMe: backData.is_on_me == '1',
    amount: +backData.amount,
  };
};
export const mapEquipStatToFront = (backData: IEquipStatDTO): IEquipWithUsagesStat => {
  return {
    ...mapEquipToFront(backData),
    parent: backData.parent_id
      ? mapEquipToFront({
          id: backData.parent_id,
          name: backData.parent_name,
          id_category: backData.parent_id_category,
          id_parent: backData.parent_id_parent,
          is_archive: backData.parent_is_archive,
          is_group: backData.parent_is_group,
          is_musthave: backData.parent_is_musthave,
          photo: backData.parent_photo,
          value: backData.parent_value,
          weight: backData.parent_weight,
        })
      : null,
    category: backData.category_id
      ? { id: +backData.category_id, name: backData.category_name }
      : null,
    usages: backData.usages.map(mapEquipStatUsageToFront),
  };
};
